#!/usr/bin/env python3
"""Fill declared DOCX placeholders without editing inputs.

Rules:
- Placeholders are {{FIELD}} and may be split across runs within one paragraph.
- Replace in body, nested tables, and all referenced (active) headers/footers.
- Conditional {{IF_RELOCATION}}...{{END_IF_RELOCATION}} is governed ONLY by
  RELOCATION_PACKAGE (required whenever the conditional appears). Keep inner
  content iff value == exactly "Yes"; any other string removes the whole block.
  RELOCATION is unused and must never be an alias/fallback.
- No cross-paragraph tokens. If a required value is missing, exit nonzero.
"""
import json, re, sys, zipfile, shutil, os

TEMPLATE = "inputs/offer_letter_template.docx"
DATA = "inputs/employee_data.json"
OUTPUT = "output/offer_letter_filled.docx"

GOVERNING = "RELOCATION_PACKAGE"
IF_TOKEN = "IF_RELOCATION"
END_IF_TOKEN = "END_IF_RELOCATION"
# Fields that participate in conditional markup (not direct substitution fields).
CONDITIONAL_TOKENS = {IF_TOKEN, END_IF_TOKEN}

TOKEN_RE = re.compile(r"\{\{([A-Z][A-Z0-9_]*)\}\}")
PARA_RE = re.compile(r"<w:p(?:\s[^>]*)?>.*?</w:p>|<w:p(?:\s[^>]*)?/>", re.DOTALL)
WT_RE = re.compile(r"(<w:t(?:\s[^>]*)?>)(.*?)(</w:t>)", re.DOTALL)

def die(msg):
    sys.stderr.write("ERROR: " + msg + "\n")
    sys.exit(1)


def load_data():
    with open(DATA, "r", encoding="utf-8") as f:
        return json.load(f)


def active_hf_parts(z):
    """Return list of header/footer part names referenced by the document."""
    doc = z.read("word/document.xml").decode("utf-8")
    rels = z.read("word/_rels/document.xml.rels").decode("utf-8")
    rid_target = {}
    for m in re.finditer(r'<Relationship\b[^>]*?Id="([^"]+)"[^>]*?Target="([^"]+)"', rels):
        rid_target[m.group(1)] = m.group(2)
    # also handle attribute order Target before Id
    for m in re.finditer(r'<Relationship\b[^>]*?Target="([^"]+)"[^>]*?Id="([^"]+)"', rels):
        rid_target.setdefault(m.group(2), m.group(1))
    parts = []
    for m in re.finditer(r'<w:(?:header|footer)Reference\b[^>]*?r:id="([^"]+)"', doc):
        rid = m.group(1)
        tgt = rid_target.get(rid)
        if tgt:
            name = "word/" + tgt if not tgt.startswith("word/") else tgt
            if name not in parts:
                parts.append(name)
    return parts


def escape_xml(s):
    return (s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;"))


def unescape_xml(s):
    return (s.replace("&lt;", "<").replace("&gt;", ">")
             .replace("&quot;", '"').replace("&apos;", "'").replace("&amp;", "&"))


def collect_para_tokens(text):
    return set(TOKEN_RE.findall(text))


def apply_substitutions(text, data, missing):
    """text is UNESCAPED plain concatenation of run text for one paragraph.
    Handle conditional first (only within this paragraph), then token subs."""
    # Conditional handling: governed solely by RELOCATION_PACKAGE.
    if IF_TOKEN in collect_para_tokens(text) or END_IF_TOKEN in collect_para_tokens(text):
        # The conditional appears -> governing field required.
        if GOVERNING not in data:
            missing.add(GOVERNING + " (required because IF_RELOCATION conditional is present)")
            return text, False
        keep = (data.get(GOVERNING) == "Yes")
        pattern = re.compile(
            r"\{\{" + IF_TOKEN + r"\}\}(.*?)\{\{" + END_IF_TOKEN + r"\}\}", re.DOTALL)
        def repl_cond(m):
            return m.group(1) if keep else ""
        text = pattern.sub(repl_cond, text)

    # Direct token substitution.
    def repl(m):
        name = m.group(1)
        if name in CONDITIONAL_TOKENS:
            return m.group(0)  # leave (should already be consumed)
        if name == "RELOCATION":
            # Present-but-unused field: there is no {{RELOCATION}} declared; if it
            # ever appears it is not a substitution target. Treat as missing data
            # only if required. Here we simply require a declared value.
            if name not in data:
                missing.add(name)
                return m.group(0)
            return data[name]
        if name not in data:
            missing.add(name)
            return m.group(0)
        return data[name]

    return TOKEN_RE.sub(repl, text), True


def process_part(xml, data, missing):
    def handle_para(pm):
        para = pm.group(0)
        wt_matches = list(WT_RE.finditer(para))
        if not wt_matches:
            return para
        # Concatenate unescaped text across runs in order.
        concat = "".join(unescape_xml(m.group(2)) for m in wt_matches)
        if "{{" not in concat:
            return para  # nothing to do, preserve exactly
        new_text, _ = apply_substitutions(concat, data, missing)
        # Redistribute: first <w:t> gets all text (escaped), others emptied.
        new_para_parts = []
        last = 0
        first_done = False
        for m in wt_matches:
            new_para_parts.append(para[last:m.start()])
            open_tag = m.group(1)
            close_tag = m.group(3)
            if not first_done:
                # Ensure xml:space preserve so leading/trailing spaces survive.
                ot = open_tag
                if "xml:space" not in ot:
                    ot = ot[:-1] + ' xml:space="preserve">'
                new_para_parts.append(ot + escape_xml(new_text) + close_tag)
                first_done = True
            else:
                new_para_parts.append(open_tag + close_tag)
            last = m.end()
        new_para_parts.append(para[last:])
        return "".join(new_para_parts)

    return PARA_RE.sub(handle_para, xml)


def main():
    data = load_data()
    missing = set()

    with zipfile.ZipFile(TEMPLATE, "r") as z:
        names = z.namelist()
        parts_to_process = ["word/document.xml"] + active_hf_parts(z)
        contents = {n: z.read(n) for n in names}

    processed = {}
    for n in parts_to_process:
        xml = contents[n].decode("utf-8")
        processed[n] = process_part(xml, data, missing)

    if missing:
        die("Missing required field(s): " + ", ".join(sorted(missing)))

    # Verify no uppercase {{TOKEN}} placeholders remain in processed parts.
    leftover = set()
    for n, xml in processed.items():
        txt = re.sub(r"<[^>]+>", "", xml)
        for t in TOKEN_RE.findall(txt):
            leftover.add(t)
    if leftover:
        die("Unresolved placeholder(s) remain: " + ", ".join(sorted(leftover)))

    os.makedirs(os.path.dirname(OUTPUT), exist_ok=True)
    # Write new zip preserving all other parts byte-for-byte.
    with zipfile.ZipFile(TEMPLATE, "r") as zin, \
         zipfile.ZipFile(OUTPUT, "w", zipfile.ZIP_DEFLATED) as zout:
        for item in zin.infolist():
            name = item.filename
            if name in processed:
                zout.writestr(item, processed[name].encode("utf-8"))
            else:
                zout.writestr(item, zin.read(name))

    print("OK: wrote", OUTPUT)


if __name__ == "__main__":
    main()
